-- Metadata only. One SELECT snapshot per project; no business/Auth rows or privileged secrets.
SELECT jsonb_build_object(
 'captured_at', statement_timestamp(),
 'server_version', current_setting('server_version'),
 'schemas', (SELECT coalesce(jsonb_agg(nspname ORDER BY nspname),'[]') FROM pg_catalog.pg_namespace WHERE nspname IN ('public','novlearn_admin_private')),
 'relations', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions,
   'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee)::text END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee,a.privilege_type,a.grantor),'[]') FROM aclexplode(coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 's'::"char" ELSE 'r'::"char" END,c.relowner))) a))
   ORDER BY n.nspname,c.relname),'[]') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','novlearn_admin_private') AND c.relkind IN ('r','p','v','m','S')),
 'columns', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'position',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default_md5',md5(pg_get_expr(d.adbin,d.adrelid)),
   'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee)::text END,'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantee,x.privilege_type,x.grantor),'[]') FROM aclexplode(a.attacl) x))
   ORDER BY n.nspname,c.relname,a.attnum),'[]') FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname IN ('public','novlearn_admin_private') AND c.relkind IN ('r','p','v','m') AND a.attnum>0 AND NOT a.attisdropped),
 'constraints', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',k.conname,'kind',k.contype,'definition',pg_get_constraintdef(k.oid,true),'validated',k.convalidated,'deferrable',k.condeferrable,'deferred',k.condeferred) ORDER BY n.nspname,c.relname,k.conname),'[]') FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','novlearn_admin_private')),
 'indexes', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',t.relname,'name',i.relname,'valid',x.indisvalid,'ready',x.indisready,'unique',x.indisunique,'definition_md5',md5(pg_get_indexdef(x.indexrelid))) ORDER BY n.nspname,t.relname,i.relname),'[]') FROM pg_index x JOIN pg_class t ON t.oid=x.indrelid JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname IN ('public','novlearn_admin_private')),
 'policies', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'command',cmd,'using',qual,'check',with_check) ORDER BY schemaname,tablename,policyname),'[]') FROM pg_policies WHERE schemaname IN ('public','novlearn_admin_private')),
 'functions', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'kind',p.prokind,'definer',p.prosecdef,'owner',pg_get_userbyid(p.proowner),'volatility',p.provolatile,'parallel',p.proparallel,'strict',p.proisstrict,'search_path',(SELECT option_value FROM pg_options_to_table(p.proconfig) WHERE option_name='search_path'),'definition_md5',md5(pg_get_functiondef(p.oid)),'definition_lf_md5',md5(replace(pg_get_functiondef(p.oid),E'\r\n',E'\n')),'body_lf_boundary_md5',md5(btrim(replace(p.prosrc,E'\r\n',E'\n'),E' \t\r\n')),
   'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee)::text END,'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantee,x.privilege_type,x.grantor),'[]') FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x))
   ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','novlearn_admin_private') AND p.prokind IN ('f','p')),
 'triggers', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'function_schema',pn.nspname,'function',p.proname,'definition_lf_md5',md5(replace(pg_get_triggerdef(t.oid,true),E'\r\n',E'\n'))) ORDER BY n.nspname,c.relname,t.tgname),'[]') FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace WHERE NOT t.tgisinternal AND (n.nspname IN ('public','novlearn_admin_private') OR (n.nspname='auth' AND c.relname='users' AND pn.nspname='public'))),
 'types', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'kind',t.typtype,'base',format_type(t.typbasetype,t.typtypmod),'not_null',t.typnotnull,'enum_labels',(SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid)) ORDER BY n.nspname,t.typname),'[]') FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname IN ('public','novlearn_admin_private') AND t.typtype IN ('e','d')),
 'sequence_parameters', (SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'type',format_type(s.seqtypid,NULL),'start',s.seqstart::text,'increment',s.seqincrement::text,'min',s.seqmin::text,'max',s.seqmax::text,'cache',s.seqcache::text,'cycle',s.seqcycle) ORDER BY n.nspname,c.relname),'[]') FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','novlearn_admin_private')),
 'default_privileges', (SELECT coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',coalesce(n.nspname,'*'),'kind',d.defaclobjtype,'acl',(SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee)::text END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee,a.privilege_type,a.grantor) FROM aclexplode(d.defaclacl) a)) ORDER BY coalesce(n.nspname,'*'),d.defaclrole,d.defaclobjtype),'[]') FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE n.nspname IN ('public','novlearn_admin_private') OR d.defaclnamespace=0),
 'roles', (SELECT coalesce(jsonb_agg(jsonb_build_object('name',rolname,'login',rolcanlogin,'inherit',rolinherit,'super',rolsuper,'bypass_rls',rolbypassrls,'createdb',rolcreatedb,'createrole',rolcreaterole,'replication',rolreplication) ORDER BY rolname),'[]') FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role','authenticator') OR rolname LIKE 'novlearn%'),
 'memberships', (SELECT coalesce(jsonb_agg(jsonb_build_object('role',pg_get_userbyid(m.roleid),'member',pg_get_userbyid(m.member),'admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option) ORDER BY pg_get_userbyid(m.roleid),pg_get_userbyid(m.member)),'[]') FROM pg_auth_members m JOIN pg_roles r ON r.oid=m.member WHERE r.rolname IN ('anon','authenticated','service_role','authenticator') OR r.rolname LIKE 'novlearn%'),
 'extensions', (SELECT coalesce(jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname) ORDER BY e.extname),'[]') FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace),
 'migration_history', (SELECT coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name,'statement_count',coalesce(cardinality(statements),0),'statements_missing',statements IS NULL,'lf_joined_md5',md5(replace(array_to_string(statements,E'\n'),E'\r\n',E'\n')),'lf_boundary_trimmed_md5',md5(btrim(replace(array_to_string(statements,E'\n'),E'\r\n',E'\n'),E' \t\r\n'))) ORDER BY version),'[]') FROM supabase_migrations.schema_migrations)
) AS metadata;
